 */
public object FfiConverterTypeRnsNode: FfiConverter<RnsNode, Long> {
    override fun lower(value: RnsNode): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): RnsNode {
        return RnsNode(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): RnsNode {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: RnsNode) = 8UL

    override fun write(value: RnsNode, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



