/**
 * Errors surfaced across the Protocol X RNS Rust core and UniFFI boundary.
 */
sealed class ProtocolxRnsException: kotlin.Exception() {
    
    class InvalidMaterial(
        
        val `detail`: kotlin.String
        ) : ProtocolxRnsException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class InvalidDestination(
        
        val `detail`: kotlin.String
        ) : ProtocolxRnsException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class NotRunning(
        ) : ProtocolxRnsException() {
        override val message
            get() = ""
    }
    
    class AlreadyRunning(
        ) : ProtocolxRnsException() {
        override val message
            get() = ""
    }
    
    class InterfaceException(
        
        val `detail`: kotlin.String
        ) : ProtocolxRnsException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class TransportException(
        
        val `detail`: kotlin.String
        ) : ProtocolxRnsException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class VerificationFailed(
        ) : ProtocolxRnsException() {
        override val message
            get() = ""
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<ProtocolxRnsException> {
        override fun lift(error_buf: RustBuffer.ByValue): ProtocolxRnsException = FfiConverterTypeProtocolxRnsError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeProtocolxRnsError : FfiConverterRustBuffer<ProtocolxRnsException> {
    override fun read(buf: ByteBuffer): ProtocolxRnsException {
        

        return when(buf.getInt()) {
            1 -> ProtocolxRnsException.InvalidMaterial(
                FfiConverterString.read(buf),
                )
            2 -> ProtocolxRnsException.InvalidDestination(
                FfiConverterString.read(buf),
                )
            3 -> ProtocolxRnsException.NotRunning()
            4 -> ProtocolxRnsException.AlreadyRunning()
            5 -> ProtocolxRnsException.InterfaceException(
                FfiConverterString.read(buf),
                )
            6 -> ProtocolxRnsException.TransportException(
                FfiConverterString.read(buf),
                )
            7 -> ProtocolxRnsException.VerificationFailed()
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: ProtocolxRnsException): ULong {
        return when(value) {
            is ProtocolxRnsException.InvalidMaterial -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is ProtocolxRnsException.InvalidDestination -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is ProtocolxRnsException.NotRunning -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is ProtocolxRnsException.AlreadyRunning -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is ProtocolxRnsException.InterfaceException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is ProtocolxRnsException.TransportException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is ProtocolxRnsException.VerificationFailed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
        }
    }

    override fun write(value: ProtocolxRnsException, buf: ByteBuffer) {
        when(value) {
            is ProtocolxRnsException.InvalidMaterial -> {
                buf.putInt(1)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is ProtocolxRnsException.InvalidDestination -> {
                buf.putInt(2)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is ProtocolxRnsException.NotRunning -> {
                buf.putInt(3)
                Unit
            }
            is ProtocolxRnsException.AlreadyRunning -> {
                buf.putInt(4)
                Unit
            }
            is ProtocolxRnsException.InterfaceException -> {
                buf.putInt(5)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is ProtocolxRnsException.TransportException -> {
                buf.putInt(6)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is ProtocolxRnsException.VerificationFailed -> {
                buf.putInt(7)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



