    override fun write(value: RnsInboundEvent, buf: ByteBuffer) {
        when(value) {
            is RnsInboundEvent.AnnounceHeard -> {
                buf.putInt(1)
                FfiConverterString.write(value.`destinationHashHex`, buf)
                FfiConverterUByte.write(value.`hops`, buf)
                Unit
            }
            is RnsInboundEvent.SinglePacketReceived -> {
                buf.putInt(2)
                FfiConverterString.write(value.`destinationHashHex`, buf)
                FfiConverterByteArray.write(value.`payload`, buf)
                Unit
            }
            is RnsInboundEvent.LinkEstablished -> {
                buf.putInt(3)
                FfiConverterString.write(value.`linkIdHex`, buf)
                FfiConverterULong.write(value.`rttMillis`, buf)
                Unit
            }
            is RnsInboundEvent.LinkPacketReceived -> {
                buf.putInt(4)
                FfiConverterString.write(value.`linkIdHex`, buf)
                FfiConverterByteArray.write(value.`payload`, buf)
                Unit
            }
            is RnsInboundEvent.LinkClosed -> {
                buf.putInt(5)
                FfiConverterString.write(value.`linkIdHex`, buf)
                Unit
            }
            is RnsInboundEvent.ResourceReceived -> {
                buf.putInt(6)
                FfiConverterString.write(value.`linkIdHex`, buf)
                FfiConverterString.write(value.`resourceHashHex`, buf)
                FfiConverterByteArray.write(value.`data`, buf)
                Unit
            }
            is RnsInboundEvent.LxmfMessageReceived -> {
                buf.putInt(7)
                FfiConverterTypeLxmfInboundMessage.write(value.`message`, buf)
                Unit
            }
            is RnsInboundEvent.LxmfDeliveryStatus -> {
                buf.putInt(8)
                FfiConverterTypeLxmfDeliveryReceipt.write(value.`receipt`, buf)
                Unit
            }
            is RnsInboundEvent.PttFrameReceived -> {
                buf.putInt(9)
                FfiConverterTypePttFramePacket.write(value.`frame`, buf)
                Unit
            }
            is RnsInboundEvent.PttFloorEvent -> {
                buf.putInt(10)
                FfiConverterTypePttFloorControlMessage.write(value.`control`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}







